import{_ as n,C as d,o as a,c as i,j as e,a as s,b as h,w as o,E as l,a7 as c,a6 as p}from"./chunks/framework.byvPrBll.js";const w=JSON.parse('{"title":"Sales Tax Computation","description":"When TaxJar calculates the tax, the data that it uses, why a document can have no tax, and what happens when a quotation becomes an order and an invoice.","frontmatter":{"title":"Sales Tax Computation","description":"When TaxJar calculates the tax, the data that it uses, why a document can have no tax, and what happens when a quotation becomes an order and an invoice.","type":"explanation"},"headers":[],"relativePath":"sales-tax/tax-computation.md","filePath":"sales-tax/tax-computation.md"}'),u={name:"sales-tax/tax-computation.md"};function x(m,t,g,f,T,y){const r=d("Mermaid");return a(),i("div",null,[t[1]||(t[1]=e("h1",{id:"tax-computation",tabindex:"-1"},[s("Tax Computation "),e("a",{class:"header-anchor",href:"#tax-computation","aria-label":'Permalink to "Tax Computation"'},"​")],-1)),t[2]||(t[2]=e("p",null,"When you save a quotation, a sales order, a sales invoice, a credit note or a debit note, the app gets the sales tax from TaxJar. You do not click a button, and any user who can save the document gets the tax.",-1)),(a(),h(c,null,{default:o(()=>[l(r,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5BYou%20save%20the%20document%5D%20--%3E%20B%5BThe%20app%20sends%20the%20data%20to%20TaxJar%5D%0A%20%20B%20--%3E%20C%5BTaxJar%20calculates%20the%20sales%20tax%5D%0A%20%20C%20--%3E%20D%5BThe%20app%20fills%20in%20the%20Sales%20Tax%20row%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=p('<p>If the data did not change since the last calculation, the app keeps the tax. Refer to <a href="#recalculation-rules">Recalculation Rules</a>.</p><h2 id="quotes-orders-invoices" tabindex="-1">Quotes, Orders &amp; Invoices <a class="header-anchor" href="#quotes-orders-invoices" aria-label="Permalink to &quot;Quotes, Orders &amp; Invoices&quot;">​</a></h2><p>All five sales documents get sales tax when you save them. Only sales invoices, credit notes and debit notes go to TaxJar when you submit them. Refer to <a href="/usa/sales-tax/pr-preview/pr-27/transaction-sync/syncing-to-taxjar">Syncing to TaxJar</a>.</p><table tabindex="0"><thead><tr><th>Document</th><th style="text-align:center;">Tax on Save</th><th style="text-align:center;">Sent on Submit</th><th>Sent As</th></tr></thead><tbody><tr><td>Quotation</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>-</td></tr><tr><td>Sales Order</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>-</td></tr><tr><td>Sales Invoice</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>TaxJar Order</td></tr><tr><td>Credit Note</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>TaxJar Refund</td></tr><tr><td>Debit Note</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>TaxJar Order</td></tr></tbody></table><h2 id="parameters-for-tax" tabindex="-1">Parameters for Tax <a class="header-anchor" href="#parameters-for-tax" aria-label="Permalink to &quot;Parameters for Tax&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Comes from</th></tr></thead><tbody><tr><td><strong>Ship from</strong></td><td>The company address with <strong>Preferred Billing Address</strong> set. TaxJar Setup sets it.</td></tr><tr><td><strong>Ship to</strong></td><td>The <strong>Shipping Address</strong> of the document. If it is empty, the app asks for one when you save.</td></tr><tr><td><strong>Items</strong></td><td>The rate, the quantity and the discount of each item row.</td></tr><tr><td><strong>Product tax category</strong></td><td>The <strong>Product Tax Category</strong> of each item. Refer to <a href="/usa/sales-tax/pr-preview/pr-27/tax-exemptions/item-tax-exemption">Item Tax Exemption</a>.</td></tr><tr><td><strong>Shipping</strong></td><td>The rows on the company&#39;s shipping ledger account.</td></tr><tr><td><strong>Other charges and discounts</strong></td><td>The other rows of the taxes table. Refer to <a href="/usa/sales-tax/pr-preview/pr-27/sales-tax/additional-charges-and-discounts">Additional Charges &amp; Discounts</a>.</td></tr><tr><td><strong>Exemption</strong></td><td>The exemption of the customer, or of the document.</td></tr><tr><td><strong>Currency</strong></td><td>A document in another currency is converted to USD with the ERPNext exchange rate. TaxJar&#39;s answer is converted back.</td></tr></tbody></table><h2 id="taxability-checks" tabindex="-1">Taxability Checks <a class="header-anchor" href="#taxability-checks" aria-label="Permalink to &quot;Taxability Checks&quot;">​</a></h2><p>TaxJar charges sales tax only when all three answers are yes. The <strong>TaxJar</strong> tab of the document shows the three answers. Refer to <a href="/usa/sales-tax/pr-preview/pr-27/sales-tax/verify-tax-applicability">Verify Tax Applicability</a>.</p><ol><li><strong>Do you have nexus in the ship-to state?</strong> If not, no tax.</li><li><strong>Is the customer taxable?</strong> An exempt customer, or a sale marked as exempt, pays no tax.</li><li><strong>Is the product taxable?</strong> The state may not tax the product tax category of an item.</li></ol><p>The state also decides which address gives the rate:</p><table tabindex="0"><thead><tr><th>State type</th><th>Rate of</th></tr></thead><tbody><tr><td><strong>Origin-based</strong></td><td>The ship-from address</td></tr><tr><td><strong>Destination-based</strong></td><td>The ship-to address</td></tr></tbody></table><h2 id="skipped-calculations" tabindex="-1">Skipped Calculations <a class="header-anchor" href="#skipped-calculations" aria-label="Permalink to &quot;Skipped Calculations&quot;">​</a></h2><p>In these cases, the app does not ask TaxJar. Every message and its fix is in <a href="/usa/sales-tax/pr-preview/pr-27/troubleshoot/messages-and-errors">Messages &amp; Errors</a>.</p><table tabindex="0"><thead><tr><th>Case</th><th>Result</th></tr></thead><tbody><tr><td><strong>The ship-to country is not the United States</strong></td><td>An export. No US sales tax.</td></tr><tr><td><strong>The document has no address</strong></td><td>No tax. The form asks for an address.</td></tr><tr><td><strong>The company does not calculate tax</strong></td><td>No tax. <strong>Compute Taxes on Sales</strong> is off for the company in TaxJar Setup, or TaxJar is off for the site.</td></tr><tr><td><strong>TaxJar cannot be reached</strong></td><td>The document saves without new tax, with an orange message. Save it again later.</td></tr></tbody></table><h2 id="recalculation-rules" tabindex="-1">Recalculation Rules <a class="header-anchor" href="#recalculation-rules" aria-label="Permalink to &quot;Recalculation Rules&quot;">​</a></h2><p>The app keeps the sales tax, and does not ask TaxJar again, when all of these are true:</p><ul><li>The data that TaxJar uses did not change. Refer to <a href="#parameters-for-tax">Parameters for Tax</a>.</li><li>The app calculated the tax in the current calendar month.</li><li>Nobody saved TaxJar Setup after the calculation.</li><li>The <strong>Sales Tax</strong> row still has the amount that TaxJar calculated.</li></ul><p>This applies when you save a document again, and when you make a sales order from a quotation or an invoice from an order. The new document keeps the tax of the source document, so one sale needs only one request to TaxJar.</p><p>The app asks TaxJar again when one of these is not true, or when you invoice only a part of an order. For example, if you change the tax amount, or add a second row on the sales tax account, the app asks TaxJar again.</p><div class="info custom-block"><p class="custom-block-title">Why a new month gets a new calculation</p><p>TaxJar always uses the rates of the day of the request, and most states and cities change rates on the first day of a month. In a new month, the app asks TaxJar again to get the current rates.</p></div>',20))])}const v=n(u,[["render",x]]);export{w as __pageData,v as default};
